def T(measure=None, max=None, ev=None, req=True):
    return {"type": "text", "required": req, **({"measure": measure} if measure else {"maxWords": max, "evidence": ev})}
def L(measure=None, max=None, ev=None, req=True):
    d = T(measure, max, ev, req); d["type"] = "link"; return d
def CONTACT(req=True):
    return {"type": "contact", "required": req, "maxWords": 2, "evidence": "cite.shell.footer"}
def ENDPOINT(req=True):
    return {"type": "endpoint", "required": req, "evidence": "cite.forms.endpoints"}
def M(ref, gen, req=True, altmax=12):
    return {"type": "media", "required": req, "maxWords": altmax, "evidence": "cite.case.chapter", "assetRoles": {"reference": ref, "generated": gen}}
def LIST(item, mn, mx=None, count=None, ev=None, req=True):
    d = {"type": "list", "required": req, "minItems": mn, "items": item}
    if count: d["count"] = count
    else: d["maxItems"] = mx; d["evidence"] = ev
    return d
def E(values, ev, req=True):
    return {"type": "enum", "required": req, "enum": values, "evidence": ev}

ART = (["owner-artwork"], ["generated-artwork-visual"])
CASEM = (["client-case-media"], ["generated-project-media"])
NAV_ITEMS = LIST(L(max=2, ev="cite.shell.menu"), 3, 6, ev="cite.shell.menu")

